public class Main {
    public static void main(String[] args) {
        int correctPin = 4321;
        int[] enteredPins = {1111, 4321};
        boolean authenticated = false;
        int pinAttempts = 0;

        // Phase 1: PIN Validation
        for (int i = 0; i < enteredPins.length; i++) {
            pinAttempts++;
            if (enteredPins[i] == correctPin) {
                authenticated = true;
                System.out.println("PIN Accepted! Welcome to Java Bank.");
                break;
            } else {
                System.out.println("Invalid PIN. Attempts remaining: " + (3 - pinAttempts));
            }
        }

        if (!authenticated) {
            System.out.println("Account Locked!");
            return;
        }

        // Phase 2: Transaction Processing
        int balance = 1000;
        int[] txs = {500, -200, -1500, 100};
        int processed = 0;
        int declined = 0;

        for (int i = 0; i < txs.length; i++) {
            int amount = txs[i];
            if (amount < 0 && Math.abs(amount) > balance) {
                System.out.println("Declined: Insufficient funds for " + amount);
                declined++;
                continue;
            }
            balance += amount;
            processed++;
            System.out.println("Tx #" + (i + 1) + " Applied: " + amount + " | Balance: $" + balance);
        }

        System.out.println("=== Session Summary ===");
        System.out.println("Total Successful: " + processed);
        System.out.println("Total Declined: " + declined);
        System.out.println("Final Balance: $" + balance);
    }
}

