public class Main {
    public static void main(String[] args) {
        int balance = 100;
        int[] wds = {-40, -80, -20};
        for (int i = 0; i < wds.length; i++) {
            int w = wds[i];
            if (Math.abs(w) > balance) {
                System.out.println("Declined: Insufficient funds for " + w);
                continue;
            }
            balance += w;
            System.out.println("Withdrew: $" + Math.abs(w) + " | Balance: $" + balance);
        }
        System.out.println("Final Balance: $" + balance);
    }
}

public class Main {
    public static void main(String[] args) {
        int amount = 380;
        int n100 = 0, n20 = 0;
        while (amount >= 100) {
            n100++;
            amount -= 100;
        }
        while (amount >= 20) {
            n20++;
            amount -= 20;
        }
        System.out.println("$100 Notes: " + n100);
        System.out.println("$20 Notes: " + n20);
        System.out.println("Remaining: $" + amount);
    }
}

public class Main {
    public static void main(String[] args) {
        int[] txs = {150, 200, 100, 120, 50};
        int total = 0;
        for (int i = 0; i < txs.length; i++) {
            int tx = txs[i];
            if (total + tx > 500) {
                System.out.println("Transaction of $" + tx + " exceeds daily limit of $500! Stopped.");
                break;
            }
            total += tx;
            System.out.println("Processed: $" + tx + " (Total: $" + total + ")");
        }
        System.out.println("Final Daily Total: $" + total);
    }
}

public class Main {
    public static void main(String[] args) {
        double balance = 1000.0;
        double[] rates = {0.05, 0.06, 0.07};
        int[] percents = {5, 6, 7};
        for (int i = 0; i < rates.length; i++) {
            balance += balance * rates[i];
            if (i < 2) {
                System.out.printf("Year %d (%d%%): Balance $%.1f%n", (i + 1), percents[i], balance);
            } else {
                System.out.printf("Year %d (%d%%): Balance $%.2f%n", (i + 1), percents[i], balance);
            }
        }
        System.out.printf("Final Balance: $%.2f%n", balance);
    }
}
